CREATE TABLE IF NOT EXISTS users(username varchar(64) PRIMARY KEY,salt varchar(128) NOT NULL,password_hash varchar(64) NOT NULL,role varchar(16) NOT NULL CHECK(role IN ('admin','viewer')));
CREATE TABLE IF NOT EXISTS sessions(token varchar(64) PRIMARY KEY,username varchar(64) REFERENCES users(username),expires timestamp with time zone NOT NULL);
CREATE TABLE IF NOT EXISTS nodes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,url varchar(2048) NOT NULL,token text NOT NULL,last_seen timestamp with time zone);
CREATE TABLE IF NOT EXISTS entries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,url varchar(2048) NOT NULL,project varchar(255) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor varchar(255) NOT NULL,action varchar(255) NOT NULL,target text NOT NULL,outcome text NOT NULL,created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS audit_login_window ON audit(actor,action,created_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
